.switch-row input:checked { background: #20534f; border-color: var(--accent); }
.switch-row input:checked::before { background: var(--accent); left: 17px; }
.reset { padding-bottom: 16px; }
.reset button { margin-bottom: 3px; }
.call { border: 1px solid var(--line); border-radius: 8px; margin: 0 0 7px; background: #101a28; overflow: hidden; }
.call summary { display: grid; align-items: center; grid-template-columns: minmax(0, 1fr) auto 74px 54px; gap: 7px 11px; padding: 10px 12px; list-style: none; }
.call summary::-webkit-details-marker { display: none; }
.call summary:hover, .call[open] summary { background: var(--surface-raised); }
.call summary:focus-visible { outline-offset: -2px; }
.call-name { padding-left: 15px; position: relative; font: 600 .85rem var(--mono); overflow-wrap: anywhere; }
.call-name::before { position: absolute; left: 0; content: "›"; color: var(--muted); }
.call[open] .call-name::before { transform: rotate(90deg); }
.call-state { padding: 1px 7px; border-radius: 5px; font-size: .71rem; background: #26354b; color: #d3deef; }
.call-state[data-state="complete"] { background: #193e3a; color: #aff1d9; }
.call-state[data-state="error"], .call-state[data-state="disconnected"] { background: #4b2935; color: var(--danger); }
.call-state[data-state="cancelled"] { background: #483a29; color: #ffda9d; }
.call-state[data-state="running"] { background: #234051; color: #a2e5f7; }
.call-time, .duration { font: .7rem var(--mono); text-align: right; color: var(--muted); white-space: nowrap; }
.progress-wrap { display: flex; align-items: center; gap: 10px; grid-column: 1 / -1; color: var(--muted); font: .74rem var(--mono); }
progress { flex: 1; accent-color: var(--accent); height: 8px; min-width: 36px; }
.payloads { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 13px; padding: 11px 13px; border-top: 1px solid var(--line); }
pre { white-space: pre-wrap; overflow-wrap: anywhere; margin: 5px 0 0; background: #0b141f; padding: 8px; border-radius: 6px; max-height: 260px; overflow: auto; font: .73rem/1.5 var(--mono); }
.approval { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 7px; padding: 10px 0; margin: 0 16px; border-top: 1px solid var(--line); font-size: .83rem; }
.approval strong { font-family: var(--mono); }
.approval button { font-size: .76rem; }
.feedback { border: 1px solid #3e736e; border-radius: 8px; padding: 8px 11px; color: var(--accent); background: #143037; font-size: .8rem; }
.feedback[data-error="true"] { color: var(--danger); border-color: #6c4554; background: #392632; }
@media (max-width: 820px) {
  .overview { grid-template-columns: 1fr 1fr; }
  .endpoint { grid-column: 1 / -1; }
  .layout { grid-template-columns: minmax(0, 1fr); }
  .sidebar { grid-row: 1; grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .feedback { grid-column: 1 / -1; }
}
@media (max-width: 490px) {
  main { width: calc(100% - 24px); margin-top: 12px; }
  .topbar { padding: 12px; }
  .sidebar { grid-template-columns: minmax(0, 1fr); }
  .call summary { grid-template-columns: minmax(0, 1fr) auto 49px; gap: 5px; }
  .call-time { display: none; }
  .payloads { grid-template-columns: minmax(0, 1fr); }
}
